// /calls/list answers once per batch; the rest of the workflow is per call.
// Drive holds duplicate copies of the same call ("name (1).wav"): identity is
// the Asterisk uniqueid, the Drive file is just storage. Keep one copy per
// uniqueid (largest file wins) so a duplicate never costs a second ASR+judge.
const { recordings = [] } = $input.first().json;
const best = new Map();
for (const r of recordings) {
  const prev = best.get(r.external_id);
  if (!prev || (r.size_bytes || 0) > (prev.size_bytes || 0)) best.set(r.external_id, r);
}
return [...best.values()].map(r => ({ json: r }));

